-- EventWise: สร้างตารางและใส่ข้อมูลในไฟล์เดียว (BigQuery SQL)
-- วิธีใช้: BigQuery Console > เลือก dataset "eventwise" > วางไฟล์นี้ทั้งหมดในช่อง query > Run

CREATE OR REPLACE TABLE `eventwise.events` (
  id STRING, name_th STRING, name_en STRING, desc_th STRING, desc_en STRING,
  category STRING, region STRING, province STRING,
  location_th STRING, location_en STRING,
  date DATE, start_time STRING, end_time STRING,
  price FLOAT64, original_price FLOAT64,
  available_seats INT64, total_seats INT64,
  image_url STRING, is_featured BOOL, is_promotion BOOL
) AS
SELECT * FROM UNNEST([
  STRUCT('evt01' AS id, 'งานสงกรานต์ สุดสนุก กรุงเทพฯ', 'Songkran Water Festival', 'เทศกาลสงกรานต์ เล่นน้ำสุดมัน พร้อมดนตรีและอาหารการกิน', 'Celebrate Songkran with water fights, music and street food.', 'event', 'central', 'Bangkok', 'ถนนข้าวสาร กรุงเทพฯ', 'Khao San Road, Bangkok', DATE '2027-04-13', '10:00', '20:00', 390, NULL, 150, 300, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/043d2a31a_generated_image.png', false, false),
  STRUCT('evt02' AS id, 'งานมหกรรมอาหารทะเล ภูเก็ต', 'Phuket Seafood Festival', 'ชิมอาหารทะเลสดใหม่ พร้อมดนตรีริมทะเลที่ภูเก็ต', 'Fresh seafood and live music by the sea in Phuket.', 'event', 'south', 'Phuket', 'หาดป่าตอง ภูเก็ต', 'Patong Beach, Phuket', DATE '2026-12-20', '16:00', '23:00', 790, NULL, 60, 120, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/f1ef78146_generated_image.png', false, false),
  STRUCT('evt03' AS id, 'คอนเสิร์ตดนตรีใต้ดาวระหว่างภูเขา เชียงใหม่', 'Mountain Music Festival - Chiang Mai', 'คอนเสิร์ตดนตรีกลางแจ้ง ใต้แสงดาวที่เชียงใหม่', 'Outdoor music concert under the stars in Chiang Mai.', 'event', 'north', 'Chiang Mai', 'ห้วยตึงเฒ่า เชียงใหม่', 'Huay Tung Tao, Chiang Mai', DATE '2026-11-30', '18:00', '23:59', 1290, 1990, 50, 150, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/c27874be6_generated_image.png', true, true),
  STRUCT('evt04' AS id, 'งานลอยกระทง เทศกาลแสงสี', 'Loy Krathong Festival', 'งานเทศกาลลอยกระทง ร่วมลอยกระทงขอช่วงให้โชคดี มีดนตรีและอาหาร', 'Join the Loy Krathong festival with music, food and floating krathongs.', 'event', 'central', 'Bangkok', 'สวนลุมพินี กรุงเทพฯ', 'Lumphini Park, Bangkok', DATE '2026-11-05', '17:00', '22:00', 590, NULL, 100, 200, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/77a26afb4_generated_image.png', true, false),
  STRUCT('evt05' AS id, 'ทัวร์วัดพระแก้ว กรุงเทพมหานคร', 'Grand Palace & Temple of Emerald Buddha - Bangkok', 'ชมความงามของพระบรมมหาราชวังและวัดพระศรีรัตนศาสดาราม', 'Grand Palace and Emerald Buddha in the heart of Bangkok.', 'tour', 'central', 'Bangkok', 'พระบรมมหาราชวัง กรุงเทพฯ', 'Grand Palace, Bangkok', DATE '2026-10-20', '09:00', '15:00', 890, 1500, 30, 40, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/043d2a31a_generated_image.png', true, true),
  STRUCT('evt06' AS id, 'ทัวร์น้ำตกพลิ้ว จันทบุรี', 'Phlio Waterfall - Chanthaburi', 'เที่ยวน้ำตกพลิ้ว ชมธรรมชาติที่อุทยานแห่งชาติคลองพลิ้ว', 'Nature trip to Phlio Waterfall in Khao Khitchakut National Park.', 'tour', 'east', 'Chanthaburi', 'น้ำตกพลิ้ว จันทบุรี', 'Phlio Waterfall, Chanthaburi', DATE '2026-12-01', '07:30', '17:00', 1090, NULL, 15, 20, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/f1ef78146_generated_image.png', false, false),
  STRUCT('evt07' AS id, 'ทัวร์หมู่บ้านจีน สันทราย อุดรธานี', 'Red Lotus Sea - Udon Thani', 'ชมทะเลบัวแดงที่หนองหาน อุดรธานี ในช่วงหนาว', 'Red Lotus Sea at Nong Han, Udon Thani in cool season.', 'tour', 'northeast', 'Udon Thani', 'ทะเลบัวแดง อุดรธานี', 'Red Lotus Sea, Udon Thani', DATE '2027-01-15', '07:00', '16:00', 990, NULL, 20, 30, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/e0a7e8fc5_generated_image.png', false, false),
  STRUCT('evt08' AS id, 'ทัวร์เกาะเสม็ด ระยอง', 'Koh Samet Island - Rayong', 'พักผ่อนบนหาดทรายขาวที่เกาะเสม็ด ระยอง', 'White sand beaches at Koh Samet, Rayong.', 'tour', 'east', 'Rayong', 'เกาะเสม็ด ระยอง', 'Koh Samet, Rayong', DATE '2026-11-15', '07:00', '19:00', 1490, NULL, 20, 30, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/f1ef78146_generated_image.png', false, false),
  STRUCT('evt09' AS id, 'ทัวร์สะพานข้ามแคว กาญจนบุรี', 'Bridge over River Kwai - Kanchanaburi', 'ชมสะพานข้ามแควน้อย และประวัติศาสตร์สมัยสงครามโลก', 'Historic Bridge over River Kwai and WWII history.', 'tour', 'west', 'Kanchanaburi', 'สะพานข้ามแคว กาญจนบุรี', 'River Kwai Bridge, Kanchanaburi', DATE '2026-10-28', '07:00', '18:00', 1190, NULL, 22, 30, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/e0a7e8fc5_generated_image.png', false, false),
  STRUCT('evt10' AS id, 'ทัวร์หัวหิน ชมวังไกล เพชรบุรี', 'Hua Hin & Phra Ratchaniwet - Phetchaburi', 'เที่ยวหัวหิน พักผ่อนริมทะเล ชมวังไกลกาญจน์', 'Relax in Hua Hin and visit the royal Maruekhathaiyawan Palace.', 'tour', 'west', 'Phetchaburi', 'หัวหิน เพชรบุรี', 'Hua Hin, Phetchaburi', DATE '2026-11-20', '08:00', '18:00', 1390, 1990, 10, 25, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/e0a7e8fc5_generated_image.png', false, true),
  STRUCT('evt11' AS id, 'ทัวร์เกาะพีพี กระบี่', 'Phi Phi Islands - Krabi', 'ล่องเรือชมเกาะพีพี ดำน้ำชมปะการัง ทะเลสีฟ้าใส', 'Island hopping and snorkeling at Phi Phi Islands, Krabi.', 'tour', 'south', 'Krabi', 'เกาะพีพี กระบี่', 'Phi Phi Islands, Krabi', DATE '2026-11-05', '07:00', '18:00', 2290, 3500, 2, 20, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/f1ef78146_generated_image.png', true, true),
  STRUCT('evt12' AS id, 'ทัวร์พัทยา ชมเกาะล้าน ชลบุรี', 'Pattaya & Koh Larn - Chonburi', 'เที่ยวทะเลพัทยา ดำน้ำชมปะการังที่เกาะล้าน', 'Beach day in Pattaya with snorkeling at Koh Larn.', 'tour', 'east', 'Chonburi', 'พัทยา ชลบุรี', 'Pattaya, Chonburi', DATE '2026-10-18', '07:00', '18:00', 1290, 2200, 4, 25, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/f1ef78146_generated_image.png', true, true),
  STRUCT('evt13' AS id, 'ทัวร์ภูเก้า-ภูผาม่าน ขอนแก่น', 'Phu Kradueng - Khon Kaen', 'ปีนเขาภูเก้า ชมทะเลหมอกบนยอดภู สัมผัสธรรมชาติอีสาน', 'Trek Phu Kradueng for misty summit views in Isan.', 'tour', 'northeast', 'Khon Kaen', 'ภูเก้า ขอนแก่น', 'Phu Kradueng, Khon Kaen', DATE '2026-11-25', '06:00', '20:00', 1790, NULL, 6, 15, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/e0a7e8fc5_generated_image.png', true, false),
  STRUCT('evt14' AS id, 'ทัวร์ดอยสุเทพ ชมวัดพระธาตุ เชียงใหม่', 'Doi Suthep Temple Tour - Chiang Mai', 'ขึ้นชมวัดพระธาตุดอยสุเทพ สถานที่ศักดิ์สิทธิ์ของชาวเชียงใหม่ พร้อมชมทัศนียภาพเมืองเชียงใหม่จากยอดดอย', 'Visit the sacred Doi Suthep temple with panoramic views of Chiang Mai city.', 'tour', 'north', 'Chiang Mai', 'ดอยสุเทพ เชียงใหม่', 'Doi Suthep, Chiang Mai', DATE '2026-10-15', '08:00', '17:00', 1290, 2500, 12, 20, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/c27874be6_generated_image.png', true, true),
  STRUCT('evt15' AS id, 'ทัวร์เกาะสมุย สุราษฎร์ธานี', 'Koh Samui Island - Surat Thani', 'พักผ่อนบนเกาะสมุย ชมหาดทรายขาวและอาทิตย์ตก', 'Relax on Koh Samui with white sand beaches and sunsets.', 'tour', 'south', 'Surat Thani', 'เกาะสมุย สุราษฎร์ธานี', 'Koh Samui, Surat Thani', DATE '2026-12-12', '07:00', '19:00', 2490, NULL, 10, 20, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/f1ef78146_generated_image.png', false, false),
  STRUCT('evt16' AS id, 'ทัวร์อยุธยา ชมเมืองมรดกโลก', 'Ayutthaya Heritage Tour', 'ชมซากปรักหักพังของอาณาจักรอยุธยา มรดกโลก', 'Explore the UNESCO ruins of ancient Ayutthaya.', 'tour', 'central', 'Ayutthaya', 'อยุธยา', 'Ayutthaya', DATE '2026-10-25', '08:30', '17:30', 990, NULL, 18, 30, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/043d2a31a_generated_image.png', false, false),
  STRUCT('evt17' AS id, 'ทัวร์เขาสามร้อยยอด ประจวบคีรีขันธ์', 'Khao Sam Roi Yot - Prachuap Khiri Khan', 'ชมอุทยานแห่งชาติเขาสามร้อยยอด ถ้ำพระยานคร', 'Explore Khao Sam Roi Yot National Park and Phraya Nakhon Cave.', 'tour', 'west', 'Prachuap Khiri Khan', 'เขาสามร้อยยอด ประจวบคีรีขันธ์', 'Khao Sam Roi Yot, Prachuap Khiri Khan', DATE '2026-12-10', '07:00', '18:00', 1290, NULL, 12, 20, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/e0a7e8fc5_generated_image.png', false, false),
  STRUCT('evt18' AS id, 'ทัวร์วัดร่องขุ่น พายเรือใต้น้ำ เชียงราย', 'White Temple & Boat Tour - Chiang Rai', 'ชมความงามของวัดร่องขุ่น และพายเรือใต้น้ำใต้ร่มเงาของต้นไม้สีเขียว', 'Explore the stunning White Temple and paddle through green waterways.', 'tour', 'north', 'Chiang Rai', 'วัดร่องขุ่น เชียงราย', 'Wat Rong Khun, Chiang Rai', DATE '2026-11-02', '07:30', '18:00', 1690, NULL, 15, 25, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/c27874be6_generated_image.png', true, false),
  STRUCT('evt19' AS id, 'ทัวร์ปางอึ๋ง สามหมู่บ้าน แม่ฮ่องสอน', 'Pang Ung & 3 Villages - Mae Hong Son', 'สัมผัสอากาศหนาวที่ปางอึ๋ง ทะเลหมอกยามเช้า และวัฒนธรรมปกาเกอะญอ', 'Misty mornings at Pang Ung and rich Karen culture.', 'tour', 'north', 'Mae Hong Son', 'ปางอึ๋ง แม่ฮ่องสอน', 'Pang Ung, Mae Hong Son', DATE '2026-12-05', '06:00', '19:00', 1990, NULL, 8, 15, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/c27874be6_generated_image.png', false, false),
  STRUCT('evt20' AS id, 'ทัวร์เกาะเกร็ด ชมปูจิ้งหนี นนทบุรี', 'Koh Kret Pottery Village - Nonthaburi', NULL, 'Pottery village island in Nonthaburi.', 'tour', 'central', 'Nakhon Pathom', 'พระปฐมเจดีย์ นครปฐม', 'Phra Pathom Chedi, Nakhon Pathom', DATE '2026-11-10', '08:00', '16:00', 690, NULL, 25, 35, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/043d2a31a_generated_image.png', false, false),
  STRUCT('evt21' AS id, 'ทัวร์เขาใหญ่ นครราชสีมา', 'Khao Yai National Park - Nakhon Ratchasima', 'เที่ยวเขาใหญ่ ชมน้ำตกและสัตว์ป่า ค้างคืนที่เขาใหญ่', 'Wildlife and waterfalls at Khao Yai National Park.', 'tour', 'northeast', 'Nakhon Ratchasima', 'เขาใหญ่ นครราชสีมา', 'Khao Yai, Nakhon Ratchasima', DATE '2026-10-30', '07:00', '19:00', 1290, NULL, 14, 20, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/e0a7e8fc5_generated_image.png', false, false),
  STRUCT('evt22' AS id, 'ทัวร์เกาะราชา ภูเก็ต', 'Racha Island - Phuket', 'ดำน้ำชมปะการังที่เกาะราชา ภูเก็ต น้ำทะเลใสสวย', 'Snorkeling at Racha Island with crystal-clear water, Phuket.', 'tour', 'south', 'Phuket', 'เกาะราชา ภูเก็ต', 'Racha Island, Phuket', DATE '2026-10-22', '07:30', '17:30', 1890, NULL, 16, 25, 'https://media.base44.com/images/public/6ab16b28950ef854d91d46b0/f1ef78146_generated_image.png', false, false)
]);

CREATE OR REPLACE TABLE `eventwise.bookings` (
  id STRING, event_id STRING, event_name STRING, event_date DATE,
  customer_name STRING, phone STRING, email STRING,
  ticket_count INT64, total_price FLOAT64,
  status STRING, payment_status STRING, payment_method STRING, created_date TIMESTAMP
) AS
SELECT * FROM UNNEST([
  STRUCT('b01' AS id, 'evt03', 'Mountain Music Festival - Chiang Mai', DATE '2026-11-30', 'สมชาย ใจดี', '081-234-5678', 'somchai@example.com', 2, 2580, 'confirmed', 'pending', TIMESTAMP 'PromptPay QR', '2026-10-15 10:30:00'),
  STRUCT('b02' AS id, 'evt05', 'Grand Palace & Temple of Emerald Buddha - Bangkok', DATE '2026-10-20', 'สุนิสา วงศ์สกุล', '082-345-6789', 'sunisa@example.com', 2, 1780, 'confirmed', 'pending', TIMESTAMP 'PromptPay QR', '2026-10-12 14:00:00'),
  STRUCT('b03' AS id, 'evt11', 'Phi Phi Islands - Krabi', DATE '2026-11-05', 'อารยา พงษ์ทอง', '083-456-7890', 'araya@example.com', 2, 4580, 'pending', 'pending', TIMESTAMP 'PromptPay QR', '2026-10-18 09:20:00'),
  STRUCT('b04' AS id, 'evt14', 'Doi Suthep Temple Tour - Chiang Mai', DATE '2026-10-15', 'ธนกร ศรีสุข', '084-567-8901', 'thanakorn@example.com', 3, 3870, 'confirmed', 'pending', TIMESTAMP 'PromptPay QR', '2026-10-10 11:45:00'),
  STRUCT('b05' AS id, 'evt01', 'Songkran Water Festival', DATE '2027-04-13', 'ปิยะพร มั่นคง', '085-678-9012', 'piyaporn@example.com', 4, 1560, 'pending', 'pending', TIMESTAMP 'PromptPay QR', '2026-10-19 16:10:00'),
  STRUCT('b06' AS id, 'evt12', 'Pattaya & Koh Larn - Chonburi', DATE '2026-10-18', 'กิตติ แสงทอง', '086-789-0123', 'kitti@example.com', 2, 2580, 'cancelled', 'pending', TIMESTAMP 'PromptPay QR', '2026-10-08 13:00:00')
]);

